 34→function AppContent({
 35→  tables,
 36→  refreshTables,
 37→  sessionId,
 38→}: {
 39→  tables: TableInfo[];
 40→  refreshTables: () => Promise<void>;
 41→  sessionId: string;
 42→}) {
 43→  const { theme, toggleTheme } = useTheme();
 44→  const { language, setLanguage, t } = useTranslation();
 45→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 46→  const [error, setError] = useState<string | { key: string; params: Record<string, string> } | null>(null);
 47→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 48→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 49→  );
 50→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 51→  const [agentOpen, setAgentOpen] = useState(true);
 52→  const [pendingSkillCommand, setPendingSkillCommand] = useState<string | null>(null);
 53→
 54→  const conversation = useConversation();
 55→  const { clearMessages, loadMessages, streamingConversationIds } = useAgent();
 56→
 57→  const handleConversationSelect = useCallback(async (id: string) => {
 58→    const outgoingId = conversation.activeConversationId;
 59→    const messages = await conversation.selectConversation(id);
 60→    loadMessages(messages, outgoingId, id);
 61→  }, [conversation, loadMessages]);
 62→
 63→  const handleNewConversation = useCallback(() => {
 64→    const outgoingId = conversation.activeConversationId;
 65→    conversation.startNewConversation();
 66→    clearMessages(outgoingId);
 67→  }, [conversation, clearMessages]);
 68→
 69→  const handleConversationDelete = useCallback(async (id: string) => {
 70→    await conversation.deleteConversation(id);
 71→    if (conversation.activeConversationId === id) {
 72→      clearMessages();
 73→    }
 74→  }, [conversation, clearMessages]);
 75→
 76→  const handleConversationRename = useCallback(async (id: string, title: string) => {
 77→    await conversation.renameConversation(id, title);
 78→  }, [conversation]);
 79→
 80→  useEffect(() => {
 81→    document.title = t('appTitle');
 82→  }, [t]);
 83→
 84→  useEffect(() => {
 85→    if (tables.length === 0) {
 86→      setQueryResult(null);
 87→      setError(null);
 88→      setEditorQuery(undefined);
 89→    }
 90→  }, [tables]);
 91→
 92→  const errorMessage = error
 93→    ? (typeof error === 'string' ? error : t(error.key, error.params))
 94→    : null;
 95→
 96→  const handleAgentToggle = () => {
 97→    setAgentOpen((prev) => !prev);
 98→  };
 99→
100→  const handleLoadSample = useCallback(async () => {
101→    setError(null);
102→    try {
103→      const response = await fetch('/api/upload/sample', { method: 'POST', headers: { 'X-Session-ID': sessionId } });
104→      if (!response.ok) throw new Error('Failed to load sample dataset');
105→      await refreshTables();
106→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
107→    } catch (e) {
108→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
109→    }
110→  }, [refreshTables, sessionId]);
111→
112→  const handleFileUpload = useCallback(
113→    async (files: File[]) => {
114→      setError(null);
115→
116→      // Check for duplicate filenames within the batch
117→      const batchDuplicates = findDuplicateFileNames(files);
118→      if (batchDuplicates.length > 0) {
119→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
120→        return;
121→      }
122→
123→      // Check for filenames that match already-uploaded table names
124→      const existingNames = new Set(tables.map((tbl) => tbl.name));
125→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
126→      if (alreadyUploaded.length > 0) {
127→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
128→        return;
129→      }
130→
131→      let lastName = '';
132→      try {
133→        for (const file of files) {
134→          const formData = new FormData();
135→          formData.append('file', file);
136→          const response = await fetch('/api/upload', {
137→            method: 'POST',
138→            headers: { 'X-Session-ID': sessionId },
139→            body: formData,
140→          });
141→          if (!response.ok) {
142→            const errorData = await response.json();
143→            throw new Error(errorData.detail || 'Failed to upload file');
144→          }
145→          const result = await response.json();
146→          // Handle both single table and array of tables (Excel with multiple sheets)
147→          if (Array.isArray(result)) {
148→            lastName = result[result.length - 1]?.name || '';
149→          } else {
150→            lastName = result.name;
151→          }
152→        }
153→        await refreshTables();
154→        if (lastName) {
155→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
156→        }
157→      } catch (e) {
158→        setError(e instanceof Error ? e.message : 'Failed to upload file');
159→      }
160→    },
161→    [refreshTables, sessionId, tables]
162→  );
163→
164→  const handleQueryExecute = useCallback(
165→    async (sql: string) => {
166→      setError(null);
167→      setQueryResult(null);
168→      try {
169→        const start = performance.now();
170→        const response = await fetch('/api/query', {
171→          method: 'POST',
172→          headers: { 'Content-Type': 'application/json', 'X-Session-ID': sessionId },
173→          body: JSON.stringify({ sql }),
174→        });
175→        const elapsed = performance.now() - start;
176→
177→        if (!response.ok) {
178→          const errorData = await response.json();
179→          throw new Error(errorData.detail || 'Query execution failed');
180→        }
181→
182→        const result = await response.json();
183→        setQueryResult({
184→          columns: result.columns,
185→          rows: result.rows,
186→          rowCount: result.rowCount,
187→          executionTimeMs: elapsed,
188→          resultType: result.resultType,
189→        });
190→        await refreshTables();
191→      } catch (e) {
192→        setError(e instanceof Error ? e.message : 'Query execution failed');
193→      }
194→    },
195→    [refreshTables, sessionId]
196→  );
197→
198→  const handleTableClick = useCallback((tableName: string) => {
199→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
200→  }, []);
201→
202→  const handleTableDelete = useCallback(async (tableName: string) => {
203→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
204→    try {
205→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
206→        method: 'DELETE',
207→        headers: { 'X-Session-ID': sessionId },
208→      });
209→      if (!response.ok) throw new Error('Failed to delete table');
210→      await refreshTables();
211→    } catch (e) {
212→      setError(e instanceof Error ? e.message : 'Failed to delete table');
213→    }
214→  }, [refreshTables, t, sessionId]);
215→
216→  const handleDeleteAll = useCallback(async () => {
217→    if (tables.length === 0) return;
218→    if (!confirm(t('deleteAllTablesConfirm'))) return;
219→    try {
220→      for (const table of tables) {
221→        const response = await fetch(`/api/tables/${encodeURIComponent(table.name)}`, {
222→          method: 'DELETE',
223→          headers: { 'X-Session-ID': sessionId },
224→        });
225→        if (!response.ok) throw new Error('Failed to delete table');
226→      }
227→      await refreshTables();
228→    } catch (e) {
229→      setError(e instanceof Error ? e.message : 'Failed to delete tables');
230→    }
231→  }, [tables, refreshTables, t, sessionId]);
232→
233→  const appClass = [
234→    'app',
235→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
236→  ].filter(Boolean).join(' ');
237→
238→  const themeIcon = theme === 'dark' ? (
239→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
240→      <circle cx="12" cy="12" r="5" />
241→      <line x1="12" y1="1" x2="12" y2="3" />
242→      <line x1="12" y1="21" x2="12" y2="23" />
243→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
244→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
245→      <line x1="1" y1="12" x2="3" y2="12" />
246→      <line x1="21" y1="12" x2="23" y2="12" />
247→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
248→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
249→    </svg>
250→  ) : (
251→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
252→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
253→    </svg>
254→  );
255→
256→  return (
257→    <div className={appClass}>
258→      <div className="app__sidebar-wrapper">
259→        <Sidebar
260→          tables={tables}
261→          onTableClick={handleTableClick}
262→          onTableDelete={handleTableDelete}
263→          onUpload={handleFileUpload}
264→          onDeleteAll={handleDeleteAll}
265→          collapsed={sidebarCollapsed}
266→          onToggle={() => setSidebarCollapsed((prev) => !prev)}
267→          onUseSkill={(name) => setPendingSkillCommand(name)}
268→          activeConversationId={conversation.activeConversationId}
269→          onConversationSelect={handleConversationSelect}
270→          onConversationNew={handleNewConversation}
271→          onConversationDelete={handleConversationDelete}
272→          onConversationRename={handleConversationRename}
273→          conversationRefreshTrigger={conversation.refreshTrigger}
274→          sessionId={sessionId}
275→          streamingConversationIds={streamingConversationIds}
276→        />
277→      </div>
278→      {agentOpen ? (
279→        <div className="app__agent-wrapper">
280→          <div className="app__header">
281→            <h1 className="app__title">{t('appTitle')}</h1>
282→            <div className="app__header-actions">
283→              <button
284→                className="app__lang-toggle"
285→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
286→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
287→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
288→              >
289→                {language === 'en' ? 'EN' : '中'}
290→              </button>
291→              <button
292→                className="app__theme-toggle"
293→                onClick={toggleTheme}
294→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
295→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
296→              >
297→                {themeIcon}
298→              </button>
299→              <button
300→                className="app__agent-toggle app__agent-toggle--active"
301→                onClick={handleAgentToggle}
302→              >
303→                {t('editorMode')}
304→              </button>
305→            </div>
306→          </div>
307→          {errorMessage && (
308→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
309→          )}
310→          <AgentPanel
311→            tables={tables}
312→            onUpload={handleFileUpload}
313→            onLoadSample={handleLoadSample}
314→            pendingSkillCommand={pendingSkillCommand}
315→            onSkillCommandConsumed={() => setPendingSkillCommand(null)}
316→          />
317→        </div>
318→      ) : (
319→        <div className="app__editor-wrapper">
320→          <div className="app__header">
321→            <h1 className="app__title">{t('appTitle')}</h1>
322→            <div className="app__header-actions">
323→              <button
324→                className="app__lang-toggle"
325→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
326→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
327→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
328→              >
329→                {language === 'en' ? 'EN' : '中'}
330→              </button>
331→              <button
332→                className="app__theme-toggle"
333→                onClick={toggleTheme}
334→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
335→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
336→              >
337→                {themeIcon}
338→              </button>
339→              <button
340→                className="app__agent-toggle"
341→                onClick={handleAgentToggle}
342→              >
343→                {t('agentMode')}
344→              </button>
345→            </div>
346→          </div>
347→          <div className="app__mode-header">
348→            <span className="app__mode-title">{t('editorMode')}</span>
349→          </div>
350→          {errorMessage && (
351→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
352→          )}
353→          <main className="app__main">
354→            {tables.length === 0 ? (
355→              <div className="app__empty">
356→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
357→              </div>
358→            ) : (
359→              <>
360→                <QueryEditor
361→                  onExecute={handleQueryExecute}
362→                  initialQuery={editorQuery}
363→                />
364→                {queryResult?.resultType === 'markdown' ? (
365→                  <ResultMarkdown result={queryResult} />
366→                ) : (
367→                  <ResultsTable result={queryResult} />
368→                )}
369→              </>
370→            )}
371→          </main>
372→        </div>
373→      )}
374→    </div>
375→  );
376→}
