378→export default function App() {
379→  const sessionId = useSessionId();
380→  const [tables, setTables] = useState<TableInfo[]>([]);
381→  const [loading, setLoading] = useState(true);
382→  const [error, setError] = useState<string | null>(null);
383→  const refreshTables = useCallback(async () => {
384→    try {
385→      const response = await fetch('/api/tables', {
386→        headers: { 'X-Session-ID': sessionId },
387→      });
388→      if (!response.ok) throw new Error('Failed to fetch tables');
389→      const data = await response.json();
390→      setTables(data);
391→    } catch (e) {
392→      console.error('Failed to refresh tables:', e);
393→    }
394→  }, [sessionId]);
395→
396→  useEffect(() => {
397→    (async () => {
398→      try {
399→        const response = await fetch('/api/health');
400→        if (!response.ok) throw new Error('Backend is not available');
401→        await refreshTables();
402→      } catch (e) {
403→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
404→      } finally {
405→        setLoading(false);
406→      }
407→    })();
408→  }, [refreshTables]);
409→
410→  if (loading) {
411→    return <div className="app-loading">Connecting to backend...</div>;
412→  }
413→
414→  if (error) {
415→    return (
416→      <div className="app-error">Failed to connect: {error}</div>
417→    );
418→  }
419→
420→  return (
421→    <ConfigProvider>
422→      <LanguageProvider>
423→        <ThemeProvider>
424→          <ConversationProvider sessionId={sessionId}>
425→            <ChartLibraryProvider>
426→              <AgentProvider refreshTables={refreshTables}>
427→                <AppContent tables={tables} refreshTables={refreshTables} sessionId={sessionId} />
428→              </AgentProvider>
429→            </ChartLibraryProvider>
430→          </ConversationProvider>
431→        </ThemeProvider>
432→      </LanguageProvider>
433→    </ConfigProvider>
434→  );
435→}
