13→interface AgentPanelProps {
14→  tables: TableInfo[];
15→  onUpload: (files: File[]) => Promise<void>;
16→  onLoadSample: () => Promise<void>;
17→  pendingSkillCommand?: string | null;
18→  onSkillCommandConsumed?: () => void;
19→}
20→
21→export function AgentPanel({ tables, onUpload, onLoadSample, pendingSkillCommand, onSkillCommandConsumed }: AgentPanelProps) {
22→  const { t } = useTranslation();
23→  const { messages, clearMessages } = useAgent();
24→  const { activeConversationId, startNewConversation } = useConversation();
25→  const { chartLibrary, setChartLibrary } = useChartLibrary();
26→  const bottomRef = useRef<HTMLDivElement>(null);
27→  const scrollContainerRef = useRef<HTMLDivElement>(null);
28→  const userScrolledUp = useRef(false);
29→
30→  const isNearBottom = useCallback(() => {
31→    const el = scrollContainerRef.current;
32→    if (!el) return true;
33→    return el.scrollHeight - el.scrollTop - el.clientHeight < 80;
34→  }, []);
35→
36→  const handleScroll = useCallback(() => {
37→    userScrolledUp.current = !isNearBottom();
38→  }, [isNearBottom]);
39→
40→  useEffect(() => {
41→    if (!userScrolledUp.current) {
42→      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
43→    }
44→  }, [messages]);
45→
46→  return (
47→    <div className="agent-panel">
48→      <div className="agent-panel__header">
49→        <span className="agent-panel__title">{t('agentMode')}</span>
50→        <div className="agent-panel__actions">
51→          <div className="agent-panel__chart-toggle">
52→            <button
53→              className={`agent-panel__chart-toggle-btn${chartLibrary === 'plotly' ? ' agent-panel__chart-toggle-btn--active' : ''}`}
54→              onClick={() => setChartLibrary('plotly')}
55→            >
56→              {t('chartLibPlotly')}
57→            </button>
58→            <button
59→              className={`agent-panel__chart-toggle-btn${chartLibrary === 'vegalite' ? ' agent-panel__chart-toggle-btn--active' : ''}`}
60→              onClick={() => setChartLibrary('vegalite')}
61→            >
62→              {t('chartLibVegaLite')}
63→            </button>
64→          </div>
65→          {messages.length > 0 && (
66→            <button className="agent-panel__clear" onClick={() => exportConversation()}>
67→              {t('export')}
68→            </button>
69→          )}
70→          {messages.length > 0 && (
71→            <button className="agent-panel__clear" onClick={() => { if (confirm(t('clearConfirm'))) { clearMessages(activeConversationId); startNewConversation(); } }}>
72→              {t('clear')}
73→            </button>
74→          )}
75→        </div>
76→      </div>
77→      <div className="agent-panel__messages" ref={scrollContainerRef} onScroll={handleScroll}>
78→        {messages.length === 0 && (
79→          <div className="agent-panel__empty">
80→            {tables.length === 0 ? (
81→              <FileUpload onUpload={onUpload} onLoadSample={onLoadSample} />
82→            ) : (
83→              t('agentEmptyState')
84→            )}
85→          </div>
86→        )}
87→        {messages.map((msg, index) => (
88→          <MessageBubble key={msg.id} message={msg} messageIndex={index} />
89→        ))}
90→        <div ref={bottomRef} />
91→      </div>
92→      <ChatInput pendingSkillCommand={pendingSkillCommand} onSkillCommandConsumed={onSkillCommandConsumed} />
93→    </div>
94→  );
95→}
