  1→/**
  2→ * Export the conversation panel as a self-contained HTML file.
  3→ *
  4→ * Strategy:
  5→ * 1. Clone the .agent-panel__messages DOM
  6→ * 2. Extract Plotly chart data before cloning (react-plotly stores .data/.layout on the el)
  7→ * 3. Remove interactive-only elements (edit/delete buttons, retry, streaming indicators)
  8→ * 4. Gather CSS from document.styleSheets
  9→ * 5. Build a standalone HTML document with embedded CSS + Plotly CDN
 10→ * 6. Trigger browser download
 11→ */
 12→
 13→interface PlotlyChartData {
 14→  data: unknown[];
 15→  layout: Record<string, unknown>;
 16→  frames?: unknown[];
 17→}
 18→
 19→function extractPlotlyCharts(container: HTMLElement): PlotlyChartData[] {
 20→  const charts: PlotlyChartData[] = [];
 21→  // react-plotly.js renders into .js-plotly-plot elements
 22→  const plotEls = container.querySelectorAll('.js-plotly-plot');
 23→  plotEls.forEach((el) => {
 24→    const plotEl = el as HTMLElement & { data?: unknown[]; layout?: Record<string, unknown>; _transitionData?: { _frames?: unknown[] } };
 25→    if (plotEl.data && plotEl.layout) {
 26→      charts.push({
 27→        data: JSON.parse(JSON.stringify(plotEl.data)),
 28→        layout: JSON.parse(JSON.stringify(plotEl.layout)),
 29→        frames: plotEl._transitionData?._frames
 30→          ? JSON.parse(JSON.stringify(plotEl._transitionData._frames))
 31→          : undefined,
 32→      });
 33→    }
 34→  });
 35→  return charts;
 36→}
 37→
 38→function gatherCSS(): string {
 39→  const rules: string[] = [];
 40→  for (const sheet of Array.from(document.styleSheets)) {
 41→    try {
 42→      for (const rule of Array.from(sheet.cssRules)) {
 43→        rules.push(rule.cssText);
 44→      }
 45→    } catch {
 46→      // Cross-origin stylesheets will throw — skip them
 47→    }
 48→  }
 49→  return rules.join('\n');
 50→}
 51→
 52→function cleanClone(clone: HTMLElement): void {
 53→  // Remove edit/delete action buttons
 54→  clone.querySelectorAll('.message-bubble__actions').forEach((el) => el.remove());
 55→  // Remove delete confirmation dialogs
 56→  clone.querySelectorAll('.message-bubble__confirm-delete').forEach((el) => el.remove());
 57→  // Remove edit mode textareas
 58→  clone.querySelectorAll('.message-bubble__edit-mode').forEach((el) => el.remove());
 59→  // Remove error retry buttons
 60→  clone.querySelectorAll('.message-bubble__error-retry').forEach((el) => el.remove());
 61→  // Remove streaming indicators
 62→  clone.querySelectorAll('.message-bubble__typing').forEach((el) => el.remove());
 63→  // Strip javascript: hrefs from user-supplied markdown links
 64→  clone.querySelectorAll('a[href^="javascript:"]').forEach((el) => el.removeAttribute('href'));
 65→}
 66→
 67→function replacePlotlyWithPlaceholders(clone: HTMLElement): void {
 68→  const plotEls = clone.querySelectorAll('.js-plotly-plot');
 69→  plotEls.forEach((el, i) => {
 70→    const placeholder = document.createElement('div');
 71→    placeholder.setAttribute('data-plotly-chart', String(i));
 72→    placeholder.style.width = '100%';
 73→    placeholder.style.minHeight = '400px';
 74→    el.parentElement?.replaceChild(placeholder, el);
 75→  });
 76→}
 77→
 78→export function exportConversation(): void {
 79→  const messagesContainer = document.querySelector('.agent-panel__messages');
 80→  if (!messagesContainer) return;
 81→
 82→  // 1. Extract Plotly data from live DOM before cloning
 83→  const charts = extractPlotlyCharts(messagesContainer as HTMLElement);
 84→
 85→  // 2. Clone the DOM
 86→  const clone = messagesContainer.cloneNode(true) as HTMLElement;
 87→
 88→  // 3. Clean up interactive-only elements
 89→  cleanClone(clone);
 90→
 91→  // 4. Replace Plotly chart elements with placeholders
 92→  replacePlotlyWithPlaceholders(clone);
 93→
 94→  // 5. Gather CSS
 95→  const css = gatherCSS();
 96→
 97→  // 6. Get current theme
 98→  const theme = document.documentElement.getAttribute('data-theme') || 'light';
 99→
100→  // 7. Get the header title text
101→  const titleEl = document.querySelector('.agent-panel__title');
102→  const title = titleEl?.textContent || 'Agent Mode';
103→
104→  // 8. Build the HTML document
105→  const html = buildHTML({ clone, css, charts, theme, title });
106→
107→  // 9. Trigger download
108→  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
109→  const url = URL.createObjectURL(blob);
110→  const a = document.createElement('a');
111→  const date = new Date().toISOString().slice(0, 10);
112→  a.href = url;
113→  a.download = `conversation-${date}.html`;
114→  document.body.appendChild(a);
115→  a.click();
116→  document.body.removeChild(a);
117→  setTimeout(() => URL.revokeObjectURL(url), 100);
118→}
