120→function buildHTML(opts: {
121→  clone: HTMLElement;
122→  css: string;
123→  charts: PlotlyChartData[];
124→  theme: string;
125→  title: string;
126→}): string {
127→  const { clone, css, charts, theme, title } = opts;
128→
129→  const chartsJSON = JSON.stringify(charts).replace(/<\//g, '<\\/');
130→
131→
132→  return `<!DOCTYPE html>
133→<html data-theme="${theme}">
134→<head>
135→<meta charset="utf-8">
136→<meta name="viewport" content="width=device-width, initial-scale=1">
137→<title>DuckDB Data Agent — Conversation Export</title>
138→${charts.length > 0 ? '<script src="https://cdn.plot.ly/plotly-2.35.2.min.js"><\/script>' : ''}
139→<style>
140→${css}
141→
142→/* Export-specific overrides */
143→body {
144→  max-width: 900px;
145→  margin: 0 auto;
146→  padding: 20px;
147→}
148→.agent-panel__messages {
149→  overflow: visible;
150→  padding: 0;
151→}
152→</style>
153→</head>
154→<body>
155→<div class="agent-panel">
156→  <div class="agent-panel__header">
157→    <span class="agent-panel__title">${escapeHTML(title)}</span>
158→  </div>
159→  ${clone.outerHTML}
160→</div>
161→${charts.length > 0 ? `<script>
162→(function() {
163→  var charts = ${chartsJSON};
164→  document.querySelectorAll('[data-plotly-chart]').forEach(function(el) {
165→    var idx = parseInt(el.getAttribute('data-plotly-chart'), 10);
166→    var chart = charts[idx];
167→    if (chart && window.Plotly) {
168→      Plotly.newPlot(el, chart.data, Object.assign({ autosize: true, height: 400 }, chart.layout), { responsive: true, displayModeBar: true });
169→    }
170→  });
171→})();
172→<\/script>` : ''}
173→</body>
174→</html>`;
175→}
176→
177→function escapeHTML(str: string): string {
178→  return str
179→    .replace(/&/g, '&amp;')
180→    .replace(/</g, '&lt;')
181→    .replace(/>/g, '&gt;')
182→    .replace(/"/g, '&quot;');
183→}
